import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { KsIconChevronDown } from '@fe-infra/keystone-icons-stencil';

const prefix = 'sub-navigation';

/**
 * @slot prefix - Slot for content to be placed before the sub nav item text, typically an icon.
 * @slot title - Slot for the main text content of the sub nav item title.
 * @slot suffix - Slot for content to be placed after the sub nav item text.
 * @slot default - Slot for the nested nav items rendered inside the expanded sub-navigation content area.
 * @part base - The base container of the component.
 */
@Component({
  styleUrl: 'styles/ks-sub-navigation.scss',
  tag: 'ks-sub-navigation',
  shadow: true,
})
export class KsSubNavigation implements ComponentInterface {
  @Element() el!: HTMLKsSubNavigationElement;
  @State() private expandedHeight = 0;

  /** The size of the nav item */
  @Prop() size: 'sm' | 'md' = 'sm';

  /** The level of the sub-navigation, starting from 0 */
  @Prop() level = 0;

  /** Whether current sub-navigation is disabled */
  @Prop() disabled?: boolean;

  /** Control whether to vertical expand the sub-navigation */
  @Prop() expanded?: boolean;

  /** Uncontrolled property to control whether to vertical expand the sub-navigation */
  @Prop() defaultExpand?: boolean;

  /** Whether the nav item is collapsed (horizontally). */
  @Prop() collapsed = false;

  @Uncontrollable('expanded', 'defaultExpand', 'ksExpand') @State() private internalExpandState?: boolean;

  /** Emits when the sub-navigation expanded state changes. */
  @Event({ composed: false, bubbles: false }) ksExpand!: EventEmitter<boolean>;

  @Slot({ slotname: 'prefix' }) private prefixSlots?: Slots;

  // ====== expand resizing observer start ======
  private itemsRef?: HTMLElement;
  private resizeObserver?: ResizeObserver;
  private roPending = false;

  private measureExpandedHeight = () => {
    const el = this.itemsRef;
    if (!el) return;
    const height = el.scrollHeight;
    if (this.expandedHeight !== height) {
      this.expandedHeight = height;
    }
  };

  private handleResize = () => {
    if (!this.internalExpandState || this.collapsed) return;
    if (this.roPending) return;
    this.roPending = true;
    requestAnimationFrame(() => {
      this.measureExpandedHeight();
      this.roPending = false;
    });
  };

  private setupResizeObserver = () => {
    if (!this.itemsRef) return;
    this.resizeObserver?.disconnect();
    this.resizeObserver = new ResizeObserver(this.handleResize);
    this.resizeObserver.observe(this.itemsRef);
  };

  @Watch('internalExpandState')
  onExpandStateChange(val: boolean) {
    if (val) {
      requestAnimationFrame(() => this.measureExpandedHeight());
      this.setupResizeObserver();
    } else {
      this.resizeObserver?.disconnect();
    }
  }
  // ====== expand resizing observer end ======

  componentWillLoad() {
    this.onExpandStateChange(this.internalExpandState || false);
  }

  disconnectedCallback(): void {
    this.resizeObserver?.disconnect();
  }

  private handleClick = () => {
    if (this.disabled) {
      return;
    }
    this.internalExpandState = !this.internalExpandState;
  };

  render() {
    return (
      <Host class="KsSubNavigation">
        <div class={`${prefix}__container`} style={{ '--ks-comp-side-navigation-level': `${this.level}` }}>
          <div
            class={{
              [prefix]: true,
              [`${prefix}--${this.size}`]: true,
              [`${prefix}--root`]: this.level < 1,
              [`${prefix}--collapsed`]: this.collapsed,
              [`${prefix}--disabled`]: this.disabled || false,
            }}
            onClick={this.handleClick}
            part="base"
          >
            {this.prefixSlots && (
              <div class={`${prefix}__prefix--wrapper`}>
                <slot name="prefix" />
              </div>
            )}

            <div class={`${prefix}__content`}>
              <slot name="title" />
            </div>

            <slot name="suffix" />

            <KsIconChevronDown
              size="14"
              class={{
                [`${prefix}__chevron`]: true,
                [`${prefix}__chevron--rotate`]: this.internalExpandState || false,
              }}
            />
          </div>

          <div
            class={{
              [`${prefix}__items`]: true,
              [`${prefix}__items--expanded`]: (this.internalExpandState && !this.collapsed) || false,
            }}
            ref={(el) => (this.itemsRef = el as HTMLElement)}
            style={{
              '--ks-comp-expanded-height': `${this.expandedHeight}px`,
            }}
          >
            <slot />
          </div>
        </div>
      </Host>
    );
  }
}
